import numpy as np
import json
from collections import Counter
from scipy import ndimage

test_input_arr = np.array(test_input)

# Count each color
color_counts = Counter()
for val in range(10):
    color_counts[val] = np.sum(test_input_arr == val)

print("Color counts:", color_counts)

# Find connected components for each non-background color
def get_components(grid, color):
    """Get label for connected components of a specific color"""
    mask = (grid == color).astype(int)
    if mask.sum() == 0:
        return 0, []
    label, n = ndimage.label(mask)
    components = []
    for i in range(1, n + 1):
        comp_cells = list(zip(*np.where(label == i)))
        components.append((len(comp_cells), comp_cells, label == i))
    return n, components

def compute_bounding_box(cells):
    """Return (min_row, max_row, min_col, max_col) for cells"""
    rows = [c[0] for c in cells]
    cols = [c[1] for c in cells]
    return (min(rows), max(rows), min(cols), max(cols))

def rect_size(box):
    """Return height * width for a bounding box"""
    return (box[1] - box[0] + 1) * (box[3] - box[0] + 1)

def pixel_count(box):
    """Return number of pixels in a bounding box"""
    return (box[1] - box[0] + 1) * (box[3] - box[0] + 1)

# Analyze each color's components
for color in [0, 1, 2, 6, 7, 8]:
    n_comp, comps = get_components(test_input_arr, color)
    print(f"\nColor {color}: {n_comp} component(s), total pixels = {color_counts[color]}")
    for idx, (size, cells, mask) in enumerate(comps):
        box = compute_bounding_box(cells)
        print(f"  Component {idx + 1}: size={size}, pixels={color_counts[color]}, bbox={box}, rect_pixels={rect_size(box)}, empty_cells={rect_size(box) - size}")

